        '«هوای تازه» (۱۳۳۶)، «باغ آینه» (۱۳۳۹) و «آیدا در آینه» (۱۳۴۱) — که با عشق به آیدا سرکیسیان سروده شده — از مجموعه‌های مهم شعر او هستند. شاملو با شکستن قالب سنتی، «شعر سپید فارسی» را بنیان گذاشت.',
        'در کنار شعر، شاملو مترجمی چیره‌دست بود: «دن آرام» شولوخف، نمایشنامه‌های برتولت برشت، «مرگ یزدگرد» بهرام بیضایی (بازنویسی) و «افسانه‌های کوچک» از ترجمه‌های مشهور او هستند. همچنین «کتاب کوچه» — فرهنگ لغات عامیانه — از آثار مهم اوست.',
        'شاملو در ۲ مرداد ۱۳۷۹ در فردیس کرج درگذشت و در امامزاده طاهر کرج، در کنار همسرش آیدا، به خاک سپرده شد. او را «پدر شعر سپید فارسی» و «شاعر آزادی» می‌دانند. شعرهایش به چندین زبان ترجمه شده و همچنان از محبوب‌ترین شاعران معاصر ایران است.',
