        'وایت در کنار «شارلوت»، «قوی کوچک» (۱۹۴۵) و «گنجشک‌ها و دیگران» را نوشت. «عناصر سبک» (۱۹۵۹) — کتابی درباره‌ی نگارش — نیز از آثار مهم اوست که سال‌ها در دانشگاه‌ها تدریس می‌شود.',
