            if (isset($expandedAuthors[$a['id']])) {
                $a = array_merge($a, $expandedAuthors[$a['id']]);
            }
        }
        unset($a);

        $validAuthors = [];
        foreach ($authors as $a) {
            if (File::exists(public_path("images/authors/{$a['id']}.jpg"))) {
                $a['photo'] = "/images/authors/{$a['id']}.jpg";
                $validAuthors[] = $a;
            }
        }
         $validBooks = [];
foreach ($books as $b) {
    $authorIsValid = collect($validAuthors)->contains('id', $b['author']);
    if (!$authorIsValid) continue;

    if (File::exists(public_path("images/books/{$b['id']}.jpg"))) {
        $b['cover'] = "/images/books/{$b['id']}.jpg";
        $validBooks[] = $b;
     }

}

        foreach ($validAuthors as $a) {
            Author::updateOrCreate(['id' => $a['id']], $a);
        }

        foreach ($validBooks as $b) {
            $b['author_id'] = $b['author'];
            unset($b['author']);
            $b['desc_long'] = $descriptions[$b['id']] ?? null;
            Book::updateOrCreate(['id' => $b['id']], $b);
        }
        
        echo "تعداد نویسنده‌های معتبر با عکس: " . count($validAuthors) . "\n";
        echo "تعداد کتاب‌های معتبر با عکس: " . count($validBooks) . "\n";
    }
